// Meeting Notes → кнопка "Открыть задачи" под таблицей Assignments
frappe.ui.form.on('Meeting Notes', {
  refresh(frm) {
    add_open_tasks_button(frm);
  },
  assignments_add(frm) {
    // при добавлении строки грид перерисовывается — вернуть кнопку
    add_open_tasks_button(frm);
  }
});

function add_open_tasks_button(frm) {
  const grid = frm.fields_dict.assignments && frm.fields_dict.assignments.grid;
  if (!grid) return;

  // не плодим дубликаты
  $(grid.wrapper).find('.mn-open-tasks-btn').remove();

  // если поддерживается API грид-кнопок — используем его
  if (grid.add_custom_button) {
    grid.add_custom_button(__('Открыть задачи'), () => open_tasks_for_note(frm), __('Действия'));
    // grid.add_custom_button рендерит в заголовке грида; дубликаты тоже чистим:
    $(grid.wrapper).find('.grid-custom-buttons .btn:contains("Открыть задачи")')
      .addClass('mn-open-tasks-btn');
    return;
  }

  // fallback: добавим кнопку в футер грида, рядом с "Add Row"
  const $btn = $(`<button type="button" class="btn btn-secondary mn-open-tasks-btn" style="margin-left:8px;">${__('Открыть задачи')}</button>`);
  $(grid.wrapper).find('.grid-footer .btn-primary').first().after($btn);
  $btn.on('click', () => open_tasks_for_note(frm));
}

function open_tasks_for_note(frm) {
  if (!frm.doc.name) return;

  // Сначала пробуем фильтровать по полю Task.meeting_notes (если оно есть)
  frappe.model.with_doctype('Task', () => {
    const hasLinkField = !!frappe.meta.get_docfield('Task', 'meeting_notes');
    if (hasLinkField) {
      frappe.route_options = { meeting_notes: frm.doc.name };
      frappe.set_route('List', 'Task');
      return;
    }

    // Если поля нет — используем ссылки на задачи из таблицы Assignments
    const ids = (frm.doc.assignments || []).map(r => r.task).filter(Boolean);
    if (ids.length) {
      frappe.route_options = { name: ['in', ids] };
      frappe.set_route('List', 'Task');
    } else {
      frappe.msgprint(__('В этом протоколе пока нет созданных задач.'));
    }
  });
}

frappe.ui.form.on('Project', {
  refresh(frm) {
    if (!frm.doc.name) return;
    frm.add_custom_button(__('Протоколы встреч'), () => {
      frappe.route_options = { project: frm.doc.name };
      frappe.set_route('List', 'Meeting Notes');
      // или: frappe.set_route('List','Meeting Notes',{ project: frm.doc.name });
    }, __('View'));
  }
});

//Тикет -- ISS-2025-01124
//Проверяем только ненулыевые значения, поскольку любое значение > 0 в estimations формирует PWE
frappe.ui.form.on('Issue', {
    refresh: function(frm) {
        //console.log('[DEBUG] Issue form refresh triggered');
        init_estimations_lock(frm);
    }
});

frappe.ui.form.on('Issue', {
    onload_post_render: function(frm) {
        //console.log('[DEBUG] Issue form refresh triggered');
        init_estimations_lock(frm);
    }
});

function init_estimations_lock(frm) {
    //console.log('[DEBUG] init_estimations_lock called');
    if (!frm.fields_dict.estimations) return;

    const lock_rows = () => {
        if (!frm.doc.estimations) return;

        frm.doc.estimations.forEach((row) => {
            const $row = $(`[data-name="${row.name}"]`);
            if (!$row.length) return;

            // --- Блокировка чекбокса удаления для оценок > 0 ---
            if (parseFloat(row.grade) > 0) {
                $row.find('.grid-row-check')
                    .prop('disabled', true)
                    .css('opacity', '0.6')
                    .css('cursor', 'not-allowed');
            } else {
                // Разблокируем если оценка = 0
                $row.find('.grid-row-check')
                    .prop('disabled', false)
                    .css('opacity', '1')
                    .css('cursor', 'pointer');
            }
        });
    };

    // Первоначальная блокировка с задержкой
    setTimeout(lock_rows, 300);
}

frappe.ui.form.on('Sales Invoice Item', {
    project: function(frm, cdt, cdn) {
        update_task_filter(frm, cdt, cdn);
    },
    
    form_render: function(frm, cdt, cdn) {
        // При отображении ряда применяем фильтр
        update_task_filter(frm, cdt, cdn);
    }
});

// Общая функция для обновления фильтра
function update_task_filter(frm, cdt, cdn) {
    let row = frappe.get_doc(cdt, cdn);
    
    // Обновляем фильтр для конкретного поля task
    let grid_row = frm.fields_dict.items.grid.grid_rows_by_docname[cdn];
    if (grid_row) {
        let task_field = grid_row.get_field('task');
        if (task_field) {
            task_field.get_query = function() {
                return {
                    filters: {
                        'project': row.project || ''
                    }
                };
            };
        }
    }
    
    // Очищаем task только если проект изменился (в событии project)
    // Для form_render очистка не нужна
    if (cur_frm.script_manager.current_trigger === 'project' && row.task) {
        frappe.model.set_value(cdt, cdn, 'task', '');
    }
}

frappe.ui.form.on('Sales Invoice', {
    onload_post_render: function(frm) {
        setup_task_filter(frm);
    },
    
    refresh: function(frm) {
        console.log ('Refresh Sales Invoice');
        setup_task_filter(frm);
    },
    
    project: function(frm) {
        setup_task_filter(frm);
        
        // Очищаем task если изменился project
        if (frm.doc.task) {
            frm.set_value('task', '');
        }
    }
});

function setup_task_filter(frm) {
    // Получаем поле task
    let task_field = frm.fields_dict.task;
    
    if (task_field) {
        task_field.get_query = function() {
            return {
                filters: {
                    'project': frm.doc.project || ''
                }
            };
        };
    }
}

 frappe.ui.form.on('Task', {
  refresh: function(frm) {
    if (frm.doc.confirm) {
      if (frm.doc.owner === frappe.session.user) {
        frm.set_df_property('status', 'options', 'Open\nCompleted');
      } else {
        frm.set_df_property('status', 'options', 'Open\nWorking\nPending Review');
      }
    } else {
      if (frm.doc.owner === frappe.session.user) {
        frm.set_df_property('status', 'options', 'Open\nWorking\nPending Review\nOverdue\nTemplate\nCompleted\nCancelled');
      } else {
        frm.set_df_property('status', 'options', 'Open\nWorking\nPending Review\nOverdue\nTemplate\nCompleted\nCancelled');
      }
    }
  }
});

frappe.ui.form.on("Task", "onload", function(frm) {
    // Проверяем, является ли текущий пользователь владельцем задачи
    if (frappe.session.user !== frm.doc.owner) {
        // Проверяем, имеет ли текущий пользователь роль Dinext_Project_Manager
        if (frappe.user.has_role("Dinext_Project_Manager")) {
            // Если роль есть, разрешаем редактирование кнопки "confirm"
            frm.toggle_enable("confirm", true);
        } else {
            // Если роли нет, отключаем кнопку "confirm"
            frm.toggle_enable("confirm", false);
        }
    } else {
        // Если текущий пользователь является владельцем, разрешаем редактирование
        frm.toggle_enable("confirm", true);
    }
});

frappe.ui.form.on('Task', {
    refresh(frm) {
        // Проверяем, есть ли у пользователя роль "Dinext_Project_Manager"
        if (!frappe.user.has_role("Dinext_Project_Manager")) {
            console.log("User does not have role: Dinext_Project_Manager");
            // Скрываем поле custom_project_team
            frm.set_df_property('custom_include', 'read_only', 1);
        } else {
            console.log("User has role: Dinext_Project_Manager");
            // Показываем поле custom_project_team, если у пользователя есть роль
            frm.set_df_property('custom_include', 'read_only', 0);
        }
    }
});

//Скорректировано наименование поля с resolution_date на sla_resolution_date
frappe.ui.form.on("Issue", {
  status: function(frm) {
    if (["Open", "Replied", "On Hold"].includes(frm.doc.status)) {
      frm.toggle_display("sla_resolution_date", false);
     } else if (frm.doc.status === "Resolved") {
      frm.toggle_display("sla_resolution_date", true);
      frm.set_value("sla_resolution_date", frappe.datetime.now_datetime());
     }  
  }
});

frappe.ui.form.on("Project", {
    // При обновлении формы устанавливаем обязательность полей
    refresh: function(frm) {
        update_mandatory_fields(frm);
    },
    
    // При изменении схемы оплаты тоже обновляем
    custom_payment_scheme: function(frm) {
        update_mandatory_fields(frm);
    },
    
    // При изменении данных в таблице тоже обновляем
    custom_ts_details_add: function(frm) {
        update_mandatory_fields(frm);
    },
    
    validate: async function(frm) {
        var participants = {};
        var virtualParticipants = {};
        
        // Массив для сбора всех ошибок
        let validationErrors = [];
        
        // Строка для сбора сообщения об отсутствии ставки себестоимости
        let costLevelErrorMessage = "";
        
        // Строка для сбора сообщения об отсутствии категории ставки реализации
        let rateCategoryErrorMessage = "";
        
        // Собираем ID всех участников, для которых нужно получить wfullname
        let workerIds = new Set();
        // Массивы для хранения информации об участниках без ставки себестоимости/категории реализации
        let participantsWithoutCostLevel = [];
        let participantsWithoutRateCategory = [];
        
        for (let index = 0; index < frm.doc.custom_ts_details.length; index++) {
            const row = frm.doc.custom_ts_details[index];
            const rowNum = index + 1;
            
            // Проверка обязательности pt_cost_level для виртуальных работников
            if (!row.pt_cost_level && row.virtual_worker) {
                participantsWithoutCostLevel.push({
                    rowNum: rowNum,
                    workerId: null, // виртуальный работник
                    pt_role: row.pt_role,
                    isVirtual: true
                });
            }
            
            // Проверка обязательности pt_category для схемы T&M
            const isTimeAndMaterials = frm.doc.custom_payment_scheme === "Время и затраты (T&M)";
            if (!row.pt_category && isTimeAndMaterials) {
                if (row.pt_worker) {
                    participantsWithoutRateCategory.push({
                        rowNum: rowNum,
                        workerId: row.pt_worker,
                        pt_role: row.pt_role,
                        isVirtual: false
                    });
                    workerIds.add(row.pt_worker);
                } else if (row.virtual_worker) {
                    participantsWithoutRateCategory.push({
                        rowNum: rowNum,
                        workerId: null,
                        pt_role: row.pt_role,
                        isVirtual: true
                    });
                }
            }
            
            // Автоматическая корректировка полей для виртуальных работников
            if (row.virtual_worker) {
                // Очищаем поля, если они заполнены
                if (row.pt_worker) {
                    row.pt_worker = null;
                }
                if (row.pt_participant_type) {
                    row.pt_participant_type = null;
                }
                if (row.pt_participant) {
                    row.pt_participant = null;
                }
                
                // Выключаем чекбоксы, если они включены
                if (row.allow_approval) {
                    row.allow_approval = 0;
                }
                if (row.pt_allow_pss) {
                    row.pt_allow_pss = 0;
                }
                if (row.notifications_on_limits) {
                    row.notifications_on_limits = 0;
                }
                
                // Проверка дублирования виртуальных работников
                var virtualKey = row.pt_role + "_" + row.pt_participant;
                
                if (virtualParticipants[virtualKey]) {
                    var existingRow = virtualParticipants[virtualKey];
                    // Проверяем пересечение периодов для виртуальных работников
                    if (row.pt_valid_from && row.pt_valid_for &&
                        existingRow.pt_valid_from && existingRow.pt_valid_for &&
                        ((row.pt_valid_from >= existingRow.pt_valid_from && row.pt_valid_from <= existingRow.pt_valid_for) ||
                        (row.pt_valid_for >= existingRow.pt_valid_from && row.pt_valid_for <= existingRow.pt_valid_for))) {
                        validationErrors.push(__("Внимание! Виртуальный работник уже назначен на роль '{0}' в пересекающийся период (строки {1} и {2})", 
                            [row.pt_role, existingRow.idx, rowNum]));
                    }
                }
                
                virtualParticipants[virtualKey] = {
                    pt_valid_from: row.pt_valid_from,
                    pt_valid_for: row.pt_valid_for,
                    idx: rowNum
                };
            } else {
                // Проверка для обычных участников
                var key = row.pt_role + "_" + row.pt_worker;
                
                if (participants[key]) {
                    var existingRow = participants[key];
                    // Проверяем пересечение периодов для обычных участников
                    if (row.pt_valid_from && row.pt_valid_for &&
                        existingRow.pt_valid_from && existingRow.pt_valid_for &&
                        ((row.pt_valid_from >= existingRow.pt_valid_from && row.pt_valid_from <= existingRow.pt_valid_for) ||
                        (row.pt_valid_for >= existingRow.pt_valid_from && row.pt_valid_for <= existingRow.pt_valid_for))) {
                        
                        // Получаем полное имя участника из таблицы Worker
                        const result = await frappe.db.get_value('Worker', row.pt_worker, 'wfullname');
                        const participantName = result.message.wfullname || row.pt_worker;
                        
                        validationErrors.push(__("Внимание! Участник '{0}' уже назначен на роль '{1}' в пересекающийся период (строки {2} и {3})", 
                            [participantName, row.pt_role, existingRow.idx, rowNum]));
                    }
                }
                
                participants[key] = {
                    pt_valid_from: row.pt_valid_from,
                    pt_valid_for: row.pt_valid_for,
                    idx: rowNum
                };
                
                // Добавляем ID работника для получения полного имени
                if (row.pt_worker) {
                    workerIds.add(row.pt_worker);
                }
            }
        }
        
        // Формируем сообщение об отсутствии ставки себестоимости для виртуальных участников
        if (participantsWithoutCostLevel.length > 0) {
            costLevelErrorMessage = __("Для виртуальных участников обязательно укажите ставку себестоимости:");
            costLevelErrorMessage += "<br><br>";
            
            participantsWithoutCostLevel.forEach(p => {
                costLevelErrorMessage += __("- {0} (строка {1})", [p.pt_role, p.rowNum]) + "<br>";
            });
            
            validationErrors.unshift(costLevelErrorMessage);
        }
        
        // Формируем сообщение об отсутствии категории ставки реализации для схемы T&M
        if (participantsWithoutRateCategory.length > 0) {
            // Получаем полные имена всех работников одним запросом для оптимизации
            let workerFullnames = {};
            if (workerIds.size > 0) {
                try {
                    const result = await frappe.db.get_list('Worker', {
                        filters: {
                            'name': ['in', Array.from(workerIds)]
                        },
                        fields: ['name', 'wfullname']
                    });
                    
                    result.forEach(worker => {
                        workerFullnames[worker.name] = worker.wfullname || worker.name;
                    });
                } catch (error) {
                    console.error('Ошибка при получении данных о работниках:', error);
                }
            }
            
            rateCategoryErrorMessage = __("При схеме 'Время и затраты (T&M)' обязательно укажите ставку реализации:");
            rateCategoryErrorMessage += "<br><br>";
            
            participantsWithoutRateCategory.forEach(p => {
                if (p.isVirtual) {
                    rateCategoryErrorMessage += __("- {0} (строка {1}, виртуальный участник)", [p.pt_role, p.rowNum]) + "<br>";
                } else {
                    const fullName = workerFullnames[p.workerId] || p.workerId;
                    rateCategoryErrorMessage += __("- {0} (строка {1}, роль: {2})", 
                        [fullName, p.rowNum, p.pt_role]) + "<br>";
                }
            });
            
            // Если уже есть сообщение о ставке себестоимости, добавляем сообщение о категории после него
            if (costLevelErrorMessage) {
                // Находим индекс первого сообщения (со ставкой себестоимости)
                const costLevelIndex = validationErrors.findIndex(msg => msg === costLevelErrorMessage);
                if (costLevelIndex !== -1) {
                    validationErrors.splice(costLevelIndex + 1, 0, rateCategoryErrorMessage);
                } else {
                    validationErrors.unshift(rateCategoryErrorMessage);
                }
            } else {
                validationErrors.unshift(rateCategoryErrorMessage);
            }
        }
        
        // Если есть ошибки валидации, показываем их все сразу
        if (validationErrors.length > 0) {
            // Создаем HTML для отображения ошибок
            let errorMessage = "";
            
            // Если только одно сообщение, не добавляем нумерацию
            if (validationErrors.length === 1) {
                errorMessage = validationErrors[0];
            } else {
                // Если несколько сообщений, показываем общий заголовок и нумерацию
                errorMessage = __("Обнаружены следующие ошибки:");
                errorMessage += "<br><br>";
                
                // Добавляем нумерованный список ошибок
                errorMessage += "<ol>";
                validationErrors.forEach(error => {
                    errorMessage += "<li>" + error + "</li>";
                });
                errorMessage += "</ol>";
            }
            
            frappe.throw(errorMessage);
        }
    }
});

