function update_mandatory_fields(frm) {
    const isTimeAndMaterials = frm.doc.custom_payment_scheme === "Время и затраты (T&M)";
    const grid = frm.fields_dict.custom_ts_details.grid;
    
    if (grid && grid.grid_rows) {
        grid.grid_rows.forEach((row, index) => {
            if (!row.fields_dict) {
                return;
            }
            
            // Берем данные из frm.doc
            const rowData = frm.doc.custom_ts_details[index];
            const isVirtualWorker = rowData ? (rowData.virtual_worker || false) : false;
            
            // Устанавливаем обязательность pt_cost_level для виртуальных работников
            if (row.fields_dict.pt_cost_level) {
                const costLevelField = row.fields_dict.pt_cost_level;
                costLevelField.df.is_mandatory = isVirtualWorker;
                costLevelField.refresh();
            }
            
            // Устанавливаем обязательность pt_category для схемы T&M
            if (row.fields_dict.pt_category) {
                const categoryField = row.fields_dict.pt_category;
                categoryField.df.is_mandatory = isTimeAndMaterials;
                categoryField.refresh();
            }
        });
    }
}

// Также обновляем обязательность при изменении virtual_worker в дочерней таблице
frappe.ui.form.on('Custom Ts Detail', {
    virtual_worker: function(frm, cdt, cdn) {
        // Получаем строку из дочерней таблицы
        const row = locals[cdt][cdn];
        
