function update_analytics_from_project(frm) {
    console.log('Getting project data for:', frm.doc.project);
    
    // Используем posting_date или текущую дату как fallback
    const referenceDate = frm.doc.posting_date || frappe.datetime.now_date();
    console.log('Using reference date:', referenceDate);
    
    // Получаем данные проекта включая дочерние таблицы  
    frappe.db.get_doc('Project', frm.doc.project)
        .then(project => {    
            console.log('Project data response:', project);
              
            // Заполняем project_portfolio из основного поля  
            if (project.custom_project_portfolio) {  
                console.log('Setting project_portfolio to:', project.custom_project_portfolio);  
                frm.set_value('project_portfolio', project.custom_project_portfolio);  
            }  
              
            // Получаем cost_center из дочерней таблицы custom_cost_center_table  
            if (project.custom_cost_center_table && project.custom_cost_center_table.length > 0) {  
                const validCostCenterRecords = project.custom_cost_center_table.filter(record =>   
                    record.cct_valid_from && record.cct_valid_from <= referenceDate  
                );  
                  
                if (validCostCenterRecords.length > 0) {  
                    // Сортируем по дате и берем ближайшую к referenceDate  
                    validCostCenterRecords.sort((a, b) =>   
                        new Date(b.cct_valid_from) - new Date(a.cct_valid_from)  
                    );  
                      
                    const closestCostCenter = validCostCenterRecords[0];  
                    if (closestCostCenter.cct_cost_center) {  
                        console.log('Setting cost_center to:', closestCostCenter.cct_cost_center);  
                        frm.set_value('cost_center', closestCostCenter.cct_cost_center);  
                    }  
                }  
            }  
              
            // Получаем business_area из дочерней таблицы custom_business_area  
            if (project.custom_business_area && project.custom_business_area.length > 0) {  
                const validBusinessAreaRecords = project.custom_business_area.filter(record =>   
                    record.valid_from && record.valid_from <= referenceDate  
                );  
                  
                if (validBusinessAreaRecords.length > 0) {  
                    // Сортируем по дате и берем ближайшую к referenceDate  
                    validBusinessAreaRecords.sort((a, b) =>   
                        new Date(b.valid_from) - new Date(a.valid_from)  
                    );  
                      
                    const closestBusinessArea = validBusinessAreaRecords[0];  
                    if (closestBusinessArea.business_area) {  
                        console.log('Setting business_area to:', closestBusinessArea.business_area);  
                        frm.set_value('business_area', closestBusinessArea.business_area);  
                    }  
                }  
            }  
        })  
        .catch(err => {  
            console.error('Error getting project data:', err);  
        });    
}

