function render_labour_percentage_chart( frm ) {
    if ( frm.aggregatedTasks && frm.dashboard.chart_area.grid && !frm.labour_percentage_chart ) {
        let labour_data = get_labour_data(frm);
        frm.labour_percentage_chart = render_linear_chart( frm.dashboard.chart_area.grid, __("Трудозатраты"), labour_data.percent, labour_data.details );
    }
